def house_bowling(rolls: list[int]) -> int:
    total = 0
    idx = 0
    for _ in range(9):
        if rolls[idx] == 10:
            total += 10 + rolls[idx + 1] + rolls[idx + 2]
            idx += 1
        else:
            frame = rolls[idx] + rolls[idx + 1]
            if frame == 10:
                total += 10 + rolls[idx + 2]
            else:
                total += frame
            idx += 2
    # Tenth frame: no bonus rolls under the house rule.
    if rolls[idx] == 10:
        total += rolls[idx]
    else:
        total += rolls[idx] + rolls[idx + 1]
    return total
